// El agente de monitoreo (G5) manda el informe: resumen y alertas. El correo va siempre al ADMIN.
const cuerpo = $input.first().json.body || {};
const alertas = Array.isArray(cuerpo.alertas) ? cuerpo.alertas : [];
if (!cuerpo.informeId) throw new Error('El aviso no trae informeId');
const hayAlta = alertas.some((a) => a.severidad === 'ALTA');
const asunto = '[CondoHub] ' + (hayAlta ? 'ALERTA ALTA' : 'Alerta') + ' del agente de monitoreo: ' + alertas.length + ' anomalía(s)';
const lineas = alertas.map((a) => '- [' + a.severidad + '] ' + a.mensaje);
const texto = [
  'El agente de monitoreo detectó anomalías en la gestión del condominio.',
  '',
  ...lineas,
  '',
  'Resumen: ' + (cuerpo.resumen || ''),
  'Informe: ' + cuerpo.informeId + ' (' + (cuerpo.generadoEn || '') + ')',
  '',
  'El agente solo observa y avisa: no tomó ninguna acción.',
].join('\n');
return [{ json: { para: $env.ADMIN_EMAIL || 'admin@condohub.test', asunto, texto, informeId: cuerpo.informeId, alertas: alertas.length } }];
